for it in _p3["items"]:
    ans = _WR[it["n"]][0]
    it["question_zh"] = "把词语排成句子：" + it["question_zh"]
    it["options"], _ = shuffle(_WR[it["n"]], ans, f"wr{it['n']}"); it["answer"] = ans
_OPT4 = {1:["6","7","8","9"],2:["2","3","4","5"],3:["1","2","3","4"],4:["70","80","90","100"]}
_p4 = _parts[3]; _p4["type"] = "choice"; _p4["instruction_mn"] = "Let's say — зургийг хараад зөв тоог сонго, дараа нь «一共» гэж найздаа хэл."
for it in _p4["items"]:
    ans = it["answer"]; it["options"], _ = shuffle(_OPT4[it["n"]], ans, f"ls{it['n']}"); it["answer"] = ans
    it["image"] = f"images/s{it['n']}.png"
_p5 = _parts[4]; _p5["type"] = "choice"; _S5 = [x["question_zh"] for x in _p5["items"]]
_p5["instruction_mn"] = "Үлгэр «季节和食物» — зураг бүрд тохирох өгүүлбэрийг сонго."
for it in _p5["items"]:
    n = int(it["answer"]); it["question_zh"] = f"季节和食物：第{n}幅图是哪一句？"
    it["question_mn"] = f"Үлгэрийн {n}-р зурагт аль өгүүлбэр тохирох вэ?"
    it["answer"] = _S5[n-1]; it["options"] = list(_S5)
# open part → speaking
for it in _parts[5]["items"]:
    workbook["speaking"]["items"].append({"n":len(workbook["speaking"]["items"])+1,"prompt_mn":"Найзтайгаа ярьж үз.","question_zh":it["question_zh"],"answer":it["answer"],"explanation_mn":it["explanation_mn"]})
del _parts[5]
dump("workbook.json", workbook)

